CREATE TABLE `purchase_requests` (`id` text PRIMARY KEY NOT NULL,`title` text NOT NULL,`status` text NOT NULL,`requester_username` text NOT NULL,`requester_name` text NOT NULL,`requester_department` text NOT NULL,`activity_id` text DEFAULT '' NOT NULL,`activity_name` text DEFAULT '' NOT NULL,`purpose` text DEFAULT '' NOT NULL,`expected_at` text DEFAULT '' NOT NULL,`estimated_total` real DEFAULT 0 NOT NULL,`actual_total` real DEFAULT 0 NOT NULL,`payee` text DEFAULT '' NOT NULL,`supplier` text DEFAULT '' NOT NULL,`order_number` text DEFAULT '' NOT NULL,`handler_name` text DEFAULT '' NOT NULL,`office_request_id` text UNIQUE,`attachments_json` text DEFAULT '[]' NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_purchase_requests_status` ON `purchase_requests` (`status`,`updated_at`);
CREATE TABLE `purchase_items` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`purchase_id` text NOT NULL,`name` text NOT NULL,`image_url` text DEFAULT '' NOT NULL,`product_url` text DEFAULT '' NOT NULL,`quantity` integer DEFAULT 1 NOT NULL,`estimated_unit_price` real DEFAULT 0 NOT NULL,`note` text DEFAULT '' NOT NULL);
CREATE INDEX `idx_purchase_items_purchase` ON `purchase_items` (`purchase_id`);
CREATE TABLE `purchase_events` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`purchase_id` text NOT NULL,`action` text NOT NULL,`from_status` text NOT NULL,`to_status` text NOT NULL,`actor_name` text NOT NULL,`note` text DEFAULT '' NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_purchase_events_purchase` ON `purchase_events` (`purchase_id`,`id`);
CREATE TABLE `dorm_rooms` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`building` text NOT NULL,`floor` text DEFAULT '' NOT NULL,`room_number` text NOT NULL,`leader_name` text DEFAULT '' NOT NULL,`contact` text DEFAULT '' NOT NULL,`resident_count` integer DEFAULT 0 NOT NULL,`note` text DEFAULT '' NOT NULL,`active` integer DEFAULT 1 NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,UNIQUE(`building`,`room_number`));
CREATE TABLE `dorm_inspection_batches` (`id` text PRIMARY KEY NOT NULL,`name` text NOT NULL,`status` text NOT NULL,`planned_date` text DEFAULT '' NOT NULL,`leader_name` text DEFAULT '' NOT NULL,`inspectors_json` text DEFAULT '[]' NOT NULL,`room_ids_json` text DEFAULT '[]' NOT NULL,`scoring_note` text DEFAULT '' NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_inspection_batches_status` ON `dorm_inspection_batches` (`status`,`updated_at`);
CREATE TABLE `dorm_inspection_records` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`batch_id` text NOT NULL,`room_id` integer NOT NULL,`hygiene_score` integer DEFAULT 0 NOT NULL,`tidiness_score` integer DEFAULT 0 NOT NULL,`safety_score` integer DEFAULT 0 NOT NULL,`issue_note` text DEFAULT '' NOT NULL,`photos_json` text DEFAULT '[]' NOT NULL,`needs_rectification` integer DEFAULT 0 NOT NULL,`rectification_deadline` text DEFAULT '' NOT NULL,`rectification_note` text DEFAULT '' NOT NULL,`review_result` text DEFAULT '' NOT NULL,`review_photos_json` text DEFAULT '[]' NOT NULL,`inspector_name` text DEFAULT '' NOT NULL,`inspected_at` text DEFAULT '' NOT NULL,`reviewer_name` text DEFAULT '' NOT NULL,`reviewed_at` text DEFAULT '' NOT NULL,UNIQUE(`batch_id`,`room_id`));
CREATE INDEX `idx_inspection_records_batch` ON `dorm_inspection_records` (`batch_id`,`room_id`);
CREATE TABLE `lost_found_items` (`id` text PRIMARY KEY NOT NULL,`name` text NOT NULL,`category` text DEFAULT '' NOT NULL,`status` text NOT NULL,`found_location` text DEFAULT '' NOT NULL,`found_at` text DEFAULT '' NOT NULL,`storage_location` text DEFAULT '' NOT NULL,`public_description` text DEFAULT '' NOT NULL,`secret_feature` text DEFAULT '' NOT NULL,`photos_json` text DEFAULT '[]' NOT NULL,`registrant_username` text NOT NULL,`registrant_name` text NOT NULL,`publish_url` text DEFAULT '' NOT NULL,`claimant_name` text DEFAULT '' NOT NULL,`claimant_student_no` text DEFAULT '' NOT NULL,`claimant_contact` text DEFAULT '' NOT NULL,`verification_note` text DEFAULT '' NOT NULL,`handler_name` text DEFAULT '' NOT NULL,`claimed_at` text DEFAULT '' NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_lost_found_status` ON `lost_found_items` (`status`,`updated_at`);
CREATE TABLE `lost_found_events` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`item_id` text NOT NULL,`action` text NOT NULL,`from_status` text NOT NULL,`to_status` text NOT NULL,`actor_name` text NOT NULL,`note` text DEFAULT '' NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE INDEX `idx_lost_found_events_item` ON `lost_found_events` (`item_id`,`id`);
